      for (let i = 0; i < raw.length; i++) ch[i] = this.lp(raw[i]);
      // \u7DDA\u6027\u5167\u63D2\u964D\u53D6\u6A23\uFF1Apos \u662F\u4E0B\u4E00\u500B\u8F38\u51FA\u6A23\u672C\u5728\u8F38\u5165\u4E2D\u7684\u4F4D\u7F6E\uFF08\u76F8\u5C0D\u65BC\u9019\u4E00\u5305\u7684\u958B\u982D\uFF0C-1 \u4EE3\u8868\u4E0A\u4E00\u5305\u6700\u5F8C\u4E00\u500B\uFF09
